const N = 56;
const sm = (t) => t * t * (3 - 2 * t);
const envAt = (env, u) => {
  if (!env) return 1;
  if (u <= env[0][0]) return env[0][1];
  for (let i = 1; i < env.length; i++) {
    if (u <= env[i][0]) { const [u0, a] = env[i - 1], [u1, b] = env[i]; return a + (b - a) * sm((u - u0) / (u1 - u0)); }
  }
  return env[env.length - 1][1];
};
const ring = (s, n) => {
  const pts = [], cy = (s.yf + s.yb) / 2, dF = cy - s.yf, dB = s.yb - cy;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * 2 * Math.PI, c = Math.cos(a), sn = Math.sin(a);
    const x = s.hw * Math.sign(c) * Math.abs(c) ** (s.px ?? 0.8);
    const e = envAt(s.env, Math.abs(x) / s.hw);
    pts.push([(s.cx ?? 0) + x, cy + e * (sn < 0 ? dF : dB) * sn]);
  }
  return pts;
};
const cr = (a, b, c, d, t) => 0.5 * (2 * b + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t * t + (-a + 3 * b - 3 * c + d) * t * t * t);
// Dense ruled loft: Catmull-Rom between key sections, point by point
const body = (keys, n = N, step = 10) => {
  const R = keys.map((k) => ring(k, n)), Z = keys.map((k) => k.z), sk = [];
  const poly = (pts, z) => { let d = draw(pts[0]); for (let i = 1; i < pts.length; i++) d = d.lineTo(pts[i]); return d.close().sketchOnPlane('XY', z); };
  for (let k = 0; k < keys.length - 1; k++) {
    const i0 = Math.max(0, k - 1), i3 = Math.min(keys.length - 1, k + 2);
    const m = Math.max(1, Math.round((Z[k + 1] - Z[k]) / step));
    for (let j = 0; j < m; j++) {
      const t = j / m;
      const pts = R[k].map((_, p) => [0, 1].map((q) => cr(R[i0][p][q], R[k][p][q], R[k + 1][p][q], R[i3][p][q], t)));
      sk.push(poly(pts, Z[k] + (Z[k + 1] - Z[k]) * t));
    }
  }
  sk.push(poly(R[keys.length - 1], Z[keys.length - 1]));
  return sk[0].loftWith(sk.slice(1), { ruled: true });
};
