const sec = (s) => {
  const pts = [], cy = (s.yf + s.yb) / 2, dF = cy - s.yf, dB = s.yb - cy, p = s.px ?? 0.92;
  for (let i = 0; i < N; i++) {
    const a = (i / N) * 2 * Math.PI, c = Math.cos(a), sn = Math.sin(a);
