    pts.push([s.cx + x, cy + (sn < 0 ? dF : dB) * sn]);
  }
  let d = draw(pts[0]);
  for (let i = 1; i < N; i++) d = d.lineTo(pts[i]);
  return d.close().sketchOnPlane('XY', s.z);
};
